The \textit{self-duality equations} for $(A, \Phi)$ are given by  
\begin{equation}
\begin{cases}
F_A + [\Phi, \Phi^*] = 0, \\
\mathrm{d}_A^{\prime\prime} \Phi = 0,
\end{cases}\label{Psd}
\end{equation}
where $A$ is a connection on $P$, $\mathrm{d}_A^{\prime\prime}$ is the holomorphic structure on $\operatorname{ad} P\otimes\mathbb{C}$ induced by $A$, and $\Phi \in \Omega^{1,0}(M, \operatorname{ad} P \otimes \mathbb{C})$.

There is an action of ${\mathscr{G}}^{\mathbb{C}}$ on $N$ given by  
\begin{equation}
N \times \mathscr{G}^\mathbb{C} \to N ; \quad (A, \Phi) \cdot g := (\tilde{A}, g^{-1} \Phi g), \quad \text{for } g \in {\mathscr{G}}^{\mathbb{C}} \text{ and } (A,\Phi) \in N, \label{cg action}
\end{equation}
where  $\tilde{A}$ denotes the Chern connection on $(V, H)$ whose $(0,1)$-component is given by $g^{-1} \mathrm{d}_A^{\prime\prime} g$.

\begin{equation}
N \times \mathscr{G}^\mathbb{C} \to N ; \quad (A, \Phi) \cdot g := (\tilde{A}, g^{-1} \Phi g), \quad \text{for } g \in {\mathscr{G}}^{\mathbb{C}} \text{ and } (A,\Phi) \in N, \label{cg action}
\end{equation}

\label{eq-conditions}
For $x \in \mathcal{O}_{(A, \Phi)}$, the following conditions are mutually equivalent:
\begin{enumerate}
    \item $x$ is a solution of class $L_1^2$ to the Hitchin self-duality equation~\eqref{hitchin-sd}.
    \item $x$ is a zero of the moment map $\mu$ as defined in~\eqref{moment map}.
    \item $x$ is a critical point of $\|\mu\|_{L^2}^2: N_1^2 \to \mathbb{R}_{\geq0}$.
    \item $x$ is a critical point of the restricted function $\left.\|\mu\|_{L^2}^2\right|_{\mathcal{O}_{(A, \Phi)}}: \mathcal{O}_{(A, \Phi)} \to \mathbb{R}_{\geq0}$.
\end{enumerate}

Let $x := (A, \Phi) \in N_1^2$ and $\mu(x) = F_A^\perp + [\Phi, \Phi^*]$. Let $Y = (\dot{A}, \dot{\Phi})$ be a tangent vector in $T_x N_1^2$. Then $\mathrm{d}_x \mu(Y)$ is an $L^2$ section of $\mathrm{End}_0 V \otimes \Lambda^2 T^*_{\mathbb{C}} M$, given by:
\begin{align}
\mathrm{d}_x \mu(Y) &= \lim_{t \to 0} \frac{1}{t} \Big( \mu(x + tY) - \mu(x) \Big) \nonumber \\
&= \lim_{t \to 0} \frac{1}{t} \Big( \big(F_{A + t\dot{A}} - F_A\big) + \big([\Phi + t\dot{\Phi}, \Phi^* + t\dot{\Phi}^*] - [\Phi, \Phi^*]\big) \Big) \nonumber \\
&= d_A \dot{A} + [\Phi, \dot{\Phi}^*] + [\dot{\Phi}, \Phi^*]. \label{dmu}
\end{align}

Suppose $\{Y_i\} := (A_i, \Phi_i)$ converges to $Y$ in $L_1^2$. Using the embedding $L_1^2 \times L_1^2 \hookrightarrow L^2$, we have $\{\mathrm{d}_x \mu(Y_i)\}$ converging to $\mathrm{d}_x \mu(Y)$ in $L^2$. On the other hand,
\[
\mathrm{d}_x \|\mu\|^2_{L^2}(Y) = 2 \left\langle \mathrm{d}_x \mu^\sharp(Y), \mu^\sharp(x) \right\rangle_{L^2}
\]
by definition. Hence, the sequence $\mathrm{d}_x \|\mu\|^2_{L^2}(Y_i)$ converges to $\mathrm{d}_x \|\mu\|^2_{L^2}(Y)$.

\begin{align}
\mathrm{d}_x \mu(Y) &= \lim_{t \to 0} \frac{1}{t} \Big( \mu(x + tY) - \mu(x) \Big) \nonumber \\
&= \lim_{t \to 0} \frac{1}{t} \Big( \big(F_{A + t\dot{A}} - F_A\big) + \big([\Phi + t\dot{\Phi}, \Phi^* + t\dot{\Phi}^*] - [\Phi, \Phi^*]\big) \Big) \nonumber \\
&= d_A \dot{A} + [\Phi, \dot{\Phi}^*] + [\dot{\Phi}, \Phi^*]. \label{dmu}
\end{align}

Suppose $\{s_i\}$ is a sequence in $\mathfrak{Lie}({\mathscr{G}^\mathbb{C}}_2^2)$ such that the fundamental vector $V^{s_i}|_x$ converges to $X \in T_x N_1^2$. Then by Lemma~\ref{FF}, $\{\mathrm{d}_A^{\prime\prime}s_i\}$ converge in $(L_1^2)^{0,1}(M, \operatorname{End}_0 V)$. We only need to show that $X \in T_x \mathcal{O}_x$, which is equivalent to finding $s \in \mathfrak{Lie}({\mathscr{G}^\mathbb{C}}_2^2)$ such that $V^s|_x=X$. First we claim that
\begin{claim}
\it $\{s_i\}$ is bounded in $L^2$
\end{claim}
If not, we may assume that $\|s_i\|_{L^2} \to \infty$. Take $s_i = \lambda_i \tilde{s}_i$ such that $\|\tilde{s}_i\|_{L^2} = 1$ and $\lambda_i = \|s_i\|_{L^2} \to \infty$. The fundamental vector of $\tilde s_i$ satisfies
\[
V^{\tilde{s}_i}\big|_x = \lambda_i^{-1} V^{s_i}\big|_x \to 0
\]
since $V^{s_i}$ converges to $X$ in $L_1^2$, which in turn gives
\begin{equation}
\mathrm{d}_A^{\prime\prime} \tilde{s}_i \xrightarrow{L_1^2} 0 \quad \text{and} \quad [\Phi, \tilde{s}_i] \xrightarrow{L_1^2} 0. \label{*3}
\end{equation}
Hence, $\mathrm{d}_A^{\prime\prime} \tilde{s}_i$ is bounded in $L_1^2$. By the elliptic estimates for $\mathrm{d}_A^{\prime\prime}$, $\tilde{s}_i$ is bounded in $L_2^2$. Therefore, we may assume $\{\tilde{s}_i\}$ has a weak limit $t$ in $L_2^2(M, \operatorname{End}_0 V)$. On the one hand, since $L_2^2$ compactly embeds into $L^2$, $\tilde{s}_i$ converges to $t$ in $L^2$. Together with $\|\tilde{s}_i\|_{L^2} = 1$, this implies $t \neq 0$. On the other hand, in the limit of \eqref{*3}
\[
\mathrm{d}_A^{\prime\prime} t = 0 \quad \text{and} \quad [\Phi, t] = 0.
\]
By Lemma~\ref{FF}, this gives $V^t|_x = 0$. Furthermore, by Corollary~\ref{s=0}, we conclude that $t = 0$, which is a contradiction. Therefore, $\|s_i\|_{L^2}$ must be bounded, and the proof of the claim is complete.

$\left\|\mathrm{d}_A^{\prime\prime}s_i\right\|_{L_1^2}$ is bounded since the sequence $\mathrm{d}_A^{\prime\prime}s_i$ converges in $L_1^2$. $\|s_i\|_{L^2}$ is bounded by the claim above. Then, by elliptic estimate for the operator $\mathrm{d}_A^{\prime\prime}$, $\|s_i\|_{L_2^2}$ is bounded. Hence, we may assume that the sequence $\{s_i\}$ weakly converges to a $s$ in $L_2^2(M, \operatorname{End}_0 V)$. Thus, $V^{s_i}|_x$ weakly converges to $V^s|_x$ in $L_1^2(M, \operatorname{End}_0 V \otimes T_\mathbb{C}^* M)$. Note that $V^{s_i}|_x$ converges to $X \in T_x N_1^2$, by the uniqueness of weak limits, we have $V^s = X$. This completes the proof of the lemma.

\label{irr}
Let $x = (A_x, \Phi_x)$ be a Higgs stable smooth pair. There exists a non-empty Zariski open subset $U \subseteq \operatorname{H}^0(M, \operatorname{End}_0 V \otimes K_M)$ such that any $\tilde{\Phi}_1 \in U$ leaves no holomorphic line subbundle of $(V, \operatorname{d}_{A_x}^{\prime\prime})$ invariant. 
Here, $\operatorname{H}^{0}(M, \operatorname{End}_0 V\otimes K_M)$ is the space of holomorphic sections of $\operatorname{End}_0 V \otimes K_M$ with respect to the holomorphic structure induced by $\operatorname{d}_{A_x}^{\prime\prime}$.
